section('14  API contracts and examples')
h('Protocol and envelopes')
add('Ordinary writes use JSON and X-Requested-With: XMLHttpRequest. Browser Origin must match the allowed origin; non-browser clients without Origin still need the header. The frontend includes credentials and a CSRF cookie token when available. Session cookie: inbox_session_id. Success usually returns { data: ... }; errors return { error: { code, message, requestId? } }. Upload and webhook bodies have special formats.')
table(['OPERATION','KEY INPUT / OUTPUT'],[('Catalog query','category, search, minPrice, maxPrice, sort, page, pageSize and merchandising flags -> products, total, page, pageSize, totalPages.'),('Cart','productId, quantity, selectedColor?, selectedSize?; update quantity by item ID. Merge takes items array.'),('Quote','items? [{productId, quantity, selectedColor?, selectedSize?}], deliveryMethod?, couponCode? -> totals with Minor equivalents, warnings, couponError?.'),('Order create','items?, shippingAddress, deliveryMethod?, paymentMethod?, couponCode?, expectedTotalMinor?, customer fields; idempotency-key header -> order, replayed? on retry.'),('Stripe session','items, shippingAddressId or shippingAddress, deliveryMethod?, couponCode? -> sessionId, url, orderNumber.'),('Order operations','status, note?, trackingNumber? for status PATCH; note? for collection. ID accepts internal ID or orderNumber.'),('Product write','name, brand, category, description, price, originalPrice, discount, stock, images, colors, sizes, specifications and feature flags. Price input is major units.'),('Review','rating, title?, comment -> upserted review and recomputed average.'),('Seller application','name?, storeName, legalName?, email, phone, businessAddress, category?, taxId?, description?, password when linking/creating account.')],[105,394])
