table(['CONTROL','IMPLEMENTATION','BOUNDARY'],[('Passwords / sessions','bcrypt (12 rounds in registration/provisioning); random 32-byte tokens; SHA-256 token hashes; 24-hour expiry.','No password reset/email verification route found.'),('Cookies','HttpOnly, Secure in production, SameSite Strict in production/Lax otherwise.','Needs HTTPS; does not remove all XSS/CSRF risk.'),('Request policy','Exact allowed origins, required X-Requested-With on unsafe requests, exact webhook exception in first guard; second CSRF layer.','Test both layers as one policy.'),('Login throttling','In-memory IP+email map; 5 attempts per 15 minutes.','Not shared across replicas; not general DDoS protection.'),('Limits','JSON/urlencoded <=1 MB; one uploaded image <=10 MB with allowed MIME types.','MIME allowlisting is not content verification.'),('Database','Prisma, foreign/unique keys and conditional stock updates.','No universal stock/rating CHECK constraint or formal proof of all logic safety.'),('Authorization','Owner filtering for personal records; admin/super-admin role guards.','Seller mutation scope/suspension need strengthening.'),('Observability','Request IDs, structured logs and sanitized production errors.','No complete monitoring/security-header middleware verified.')],[93,235,171])
